import Header from './header';
import Status from './status';
import './App.css';
import { languages } from './languages';
import React ,{useState } from 'react';




function App() {


  const [currentWord, setWord] = useState('react');
  const wordElem= currentWord.split("").map((alphabet,index)=>{
   return <span key={index}>{alphabet.toUpperCase()}</span>
  })


  const keyboard="abcdefghijklmnopqrstuvwxyz";

  const keyboardElems=keyboard.split("").map((btn,index)=>{
      return<button key={index} className='keyboard-btn'>{btn}</button>
  })


  const chipsElem = languages.map(lan => (
    <span key={lan.name} style={{
      backgroundColor: lan.backgroundColor,
      color:lan.color
    }} className='chips'>
      {lan.name}
    </span>
  ));
  return (
    <div className="App">
     <Header />
     <Status />
     <div className='chips-container'>
      {chipsElem}
     </div>
     <div className='word'>{wordElem}</div>
     <div>{}</div>
    </div>
  );
}

export default App;
